using System.Diagnostics.Metrics;
using Microsoft.Extensions.AI;

public class CostMonitoringChatClient : DelegatingChatClient
{
    private static readonly Meter s_meter = new("LearnAI.GenAI.Observability", "1.0.0");
    private static readonly Counter<long> s_tokenCounter = s_meter.CreateCounter<long>(
        "gen_ai.client.token.usage",
        "token",
        "Number of tokens consumed across AI operations");
    private static readonly Histogram<double> s_latencyHistogram = s_meter.CreateHistogram<double>(
        "gen_ai.client.operation.duration",
        "ms",
        "Latency of LLM completion calls in milliseconds");

    public CostMonitoringChatClient(IChatClient inner) : base(inner) { }

    public override async Task<ChatCompletion> CompleteAsync(
        IList<ChatMessage> chatMessages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var sw = Stopwatch.StartNew();
        ChatCompletion response = await base.CompleteAsync(chatMessages, options, cancellationToken);
        sw.Stop();

        var modelName = options?.ModelId ?? "default-model";
        var tenantId = options?.AdditionalProperties?.TryGetValue("TenantId", out var t) == true ? t?.ToString() : "unknown";

        if (response.Usage != null)
        {
            var inputTokens = response.Usage.InputTokenCount ?? 0;
            var outputTokens = response.Usage.OutputTokenCount ?? 0;

            // Record standard GenAI metric dimensions
            s_tokenCounter.Add(inputTokens, 
                new KeyValuePair<string, object?>("token_type", "input"),
                new KeyValuePair<string, object?>("model", modelName),
                new KeyValuePair<string, object?>("tenant_id", tenantId));

            s_tokenCounter.Add(outputTokens,
                new KeyValuePair<string, object?>("token_type", "output"),
                new KeyValuePair<string, object?>("model", modelName),
                new KeyValuePair<string, object?>("tenant_id", tenantId));
        }

        s_latencyHistogram.Record(sw.Elapsed.TotalMilliseconds,
            new KeyValuePair<string, object?>("model", modelName),
            new KeyValuePair<string, object?>("tenant_id", tenantId));

        return response;
    }
}
